import axios from 'axios';

export const fetchPlaces = async (filters) => {
    try {
        const response = await axios.get('http://localhost:5000/api/places', { params: filters });
        return response.data;
    } catch (error) {
        console.error('Error fetching places:', error);
        throw error;
    }
};
